use std::collections::BTreeMap;
use std::error::Error;
use std::fs;
use std::path::PathBuf;
use truenorth_mcp::engine::workspace_upgrade::bundle::DesiredFile;
use truenorth_mcp::engine::workspace_upgrade::manifest::WorkspaceManifest;
use truenorth_mcp::engine::workspace_upgrade::{plan, transaction};

fn main() -> Result<(), Box<dyn Error>> {
    let root = PathBuf::from(std::env::args().nth(1).ok_or("fixture root required")?);
    let installed = WorkspaceManifest::read_optional(&root)?.ok_or("manifest required")?;
    let mut desired = BTreeMap::new();
    for (path, record) in &installed.managed {
        desired.insert(path.clone(), DesiredFile { path: path.clone(), bytes: fs::read(root.join(path))?, mode: record.mode.clone() });
    }
    let profile = desired.get_mut(".agent/profile.yml").ok_or("profile must be managed")?;
    profile.bytes = b"profile: not-a-profile\n".to_vec();
    let prepared = plan::build_plan(&root, &desired, Some(&installed), &installed.bundle_version, &installed.workspace_schema_version, &installed.profile, installed.skill_sets.clone())?;
    assert_eq!(prepared.counts.update, 1);
    transaction::prepare(&root, &prepared, &desired)?;
    println!("prepared real pending transaction with invalid profile postimage");
    Ok(())
}
